									),
									array(
										'titre' => 'Ce qu\'un prestataire ne remplace pas',
										'titre_tag' => 'h3',
										'description' => 'Un prestataire externe n\'est pas présent en continu dans vos locaux et n\'assure pas les gestes du quotidien entre deux passages. Si votre besoin réel est une présence permanente, une embauche directe reste probablement plus adaptée — nous le disons plutôt que de forcer un devis.',
										'lignes' => array(),
										'badge' => '',
										'provisoire' => false,
										'surtitre' => '',
										'icone' => '',
										'image' => '',
