								'texte' => 'Ce sont les contraintes qui diffèrent, et elles déterminent tout : l\'heure du passage, l\'ordre des priorités, la gestion des accès, le périmètre exclu. Un commerce se traite avant l\'ouverture sur un créneau non extensible ; un cabinet, après le départ du dernier patient ; une copropriété, à jour fixe validé par le syndic ; un meublé, sur le créneau disponible entre deux occupants. Chaque page détaille ces contraintes, une semaine type et les limites explicites de la prestation.',
