				'blocs' => array(
					array(
						'titre' => 'Départements, villes et communes : comment lire ces pages',
						'niveau' => 'h2',
						'grille' => false,
						'colonnes' => 1,
						'sequence' => array(
							array(
								'type' => 'paragraph',
								'texte' => 'Chaque département dispose de sa page : villes couvertes, tissu professionnel local, types de locaux les plus fréquents, organisation des déplacements et questions fréquentes. Chaque ville principale a également la sienne, plus détaillée : espaces et tâches, fréquences, horaires, accès aux locaux, exemple de budget, quartiers et zones d\'activité, communes réellement proches.',
							),
							array(
								'type' => 'paragraph',
								'texte' => 'Nous distinguons volontairement trois niveaux de proximité : les communes voisines, les autres villes du même département, et les autres secteurs couverts en région. Besançon, Nevers ou Vesoul sont des secteurs régionaux couverts, pas des communes voisines de Dijon : nous préférons l\'écrire clairement plutôt que de gonfler artificiellement une liste de liens.',
							),
						),
						'cartes' => array(),
						'textes' => array(
							'Chaque département dispose de sa page : villes couvertes, tissu professionnel local, types de locaux les plus fréquents, organisation des déplacements et questions fréquentes. Chaque ville principale a également la sienne, plus détaillée : espaces et tâches, fréquences, horaires, accès aux locaux, exemple de budget, quartiers et zones d\'activité, communes réellement proches.',
							'Nous distinguons volontairement trois niveaux de proximité : les communes voisines, les autres villes du même département, et les autres secteurs couverts en région. Besançon, Nevers ou Vesoul sont des secteurs régionaux couverts, pas des communes voisines de Dijon : nous préférons l\'écrire clairement plutôt que de gonfler artificiellement une liste de liens.',
						),
						'liste' => array(),
