						'noms' => array(),
						'citations' => array(),
						'faq' => array(),
						'etapes' => array(),
					),
					array(
						'titre' => 'Les espaces que nous traitons — et ceux que nous ne traitons pas',
						'niveau' => 'h2',
						'grille' => false,
						'colonnes' => 1,
						'sequence' => array(
							array(
								'type' => 'paragraph',
								'texte' => 'Notre offre couvre les bureaux, les accueils, les locaux administratifs, les parties communes d\'immeubles, les commerces et les cabinets courants. Lorsqu\'une zone d\'activité accueille de l\'industrie, de la logistique, de l\'agroalimentaire ou des établissements de santé, nous intervenons uniquement sur les espaces compatibles avec cette offre : bureaux administratifs, salles de réunion, vestiaires de bureau, halls et sanitaires.',
							),
							array(
								'type' => 'paragraph',
								'texte' => 'Nous ne réalisons pas de nettoyage industriel lourd, de nettoyage de chaînes de production, de nettoyage agroalimentaire spécialisé, de bio-nettoyage hospitalier, de traitement chimique, de désamiantage ni d\'intervention en locaux à risque. Si votre besoin relève de ces domaines, nous le disons dès le premier échange plutôt que de vous faire perdre du temps.',
							),
						),
						'cartes' => array(),
						'textes' => array(
							'Notre offre couvre les bureaux, les accueils, les locaux administratifs, les parties communes d\'immeubles, les commerces et les cabinets courants. Lorsqu\'une zone d\'activité accueille de l\'industrie, de la logistique, de l\'agroalimentaire ou des établissements de santé, nous intervenons uniquement sur les espaces compatibles avec cette offre : bureaux administratifs, salles de réunion, vestiaires de bureau, halls et sanitaires.',
							'Nous ne réalisons pas de nettoyage industriel lourd, de nettoyage de chaînes de production, de nettoyage agroalimentaire spécialisé, de bio-nettoyage hospitalier, de traitement chimique, de désamiantage ni d\'intervention en locaux à risque. Si votre besoin relève de ces domaines, nous le disons dès le premier échange plutôt que de vous faire perdre du temps.',
