						'niveau' => 'h2',
						'grille' => false,
						'colonnes' => 1,
						'sequence' => array(
							array(
								'type' => 'paragraph',
								'texte' => 'Les pages publiées correspondent à nos secteurs prioritaires. Elles ne délimitent pas notre périmètre : nous intervenons dans de nombreuses communes qui n\'ont pas encore de page dédiée, dès lors que le trajet et la fréquence permettent une organisation stable.',
							),
							array(
								'type' => 'paragraph',
								'texte' => 'Le plus simple reste de nous donner votre adresse et votre besoin : nous vous confirmons sous 24 heures si nous pouvons intervenir, à quel rythme, et à quelles conditions. Si nous ne sommes pas en mesure de tenir un planning fiable chez vous, nous vous le disons plutôt que de nous engager à moitié.',
